var r=42;var s=`042-grating-zesting-crushing-and-mashing`;var i=`031`;var a={en:`Grating, Zesting, Crushing, and Mashing`,ua:`Натирання, зняття цедри, роздавлювання та розминання`};var n={short:`Grating and zesting increase exposed surface area, while crushing and mashing break tissue more aggressively. Choosing the technique controls texture, extraction, and flavor release.`,sections:[{title:`Core idea`,text:`Coarse grating creates larger shreds for salads or fritters; fine grating disperses cheese, garlic, ginger, or hard spices more evenly. Zesting removes only the intensely aromatic outer colored citrus skin, avoiding as much bitter white pith as possible. Shredding creates longer, finer strips, often for cabbage.`},{title:`Scientific / practical principles`,text:`Thin fragments have more exposed surface area per gram, accelerating moisture loss, seasoning uptake, and flavor release. Gentle grating preserves distinct shreds; excessive pressure can crush ingredients and make them wet or mushy.`},{title:`How to apply it`,text:`Choose the correct hole size or mandoline setting, secure the tool, and grate away from the fingers. Use a hand guard for small pieces and a food processor for large quantities. Wash citrus thoroughly, then rotate the fruit and stop at the white pith.`},{title:`Practical example`,text:`For lemon pasta, grate a small amount of zest directly over the finished sauce to preserve volatile aromas. For carrot fritters, coarse-grate carrots, then consider squeezing excess moisture before mixing.`},{title:`Common mistakes and limitations`,text:`Never use the last slippery piece bare-handed on a sharp grater or mandoline. Do not confuse zest with the entire peel, and account for water released by finely grated produce when adjusting recipe consistency.`},{title:`Crushing and mashing`,text:`Crushed garlic releases pungent sulfur compounds rapidly; mashed cooked potatoes can become sticky if overworked, because starch is released. For citrus zest, remove the colored outer layer without much bitter white pith; wash citrus before zesting.`},{title:`Related theories`,text:`038, 039, 053.`}]};var o={short:`Натирання та зняття цедри збільшують площу відкритої поверхні, а роздавлювання й розминання сильніше руйнують тканини продукту. Спосіб обробки визначає текстуру й швидкість вивільнення смаку.`,sections:[{title:`Суть`,text:`Велика тертка дає помітну стружку для салатів чи оладок, дрібна рівномірніше розподіляє сир, часник, імбир та тверді спеції. Цедра є ароматним зовнішнім забарвленим шаром цитрусової шкірки, який знімають без значної кількості гіркого білого шару. Шаткування утворює довгі тонкі смужки, наприклад із капусти.`},{title:`Наукові та практичні принципи`,text:`Тонкі частинки мають більшу відкриту поверхню на одиницю маси, тому швидше віддають вологу, поглинають приправи й вивільняють аромат. Акуратне натирання зберігає окремі волокна, а надмірний тиск може розчавити продукт і зробити його водянистим.`},{title:`Як застосовувати`,text:`Доберіть розмір отворів тертки або налаштування шатківниці, надійно зафіксуйте інструмент і тримайте пальці подалі від робочої поверхні. Для маленьких шматків користуйтеся захисним тримачем, а для великих обсягів користуйтеся комбайном. Ретельно помийте цитрус, знімайте цедру з різних боків і зупиніться на білому шарі.`},{title:`Практичний приклад`,text:`Для пасти з лимоном натріть трохи цедри безпосередньо в готовий соус, щоб зберегти леткі аромати. Для морквяних оладок натріть моркву крупно й за потреби відіжміть зайву вологу перед змішуванням.`},{title:`Поширені помилки й обмеження`,text:`Не натирайте останній слизький шматочок голими пальцями на гострій тертці чи шатківниці. Не плутайте цедру з усією шкіркою, а під час коригування рецепта враховуйте вологу, що виділяється з дрібно натертих овочів.`},{title:`Роздавлювання й розминання`,text:`Роздавлений часник швидко виділяє пекучі сірковмісні сполуки; картопляне пюре стає клейким від надмірного перемішування через вивільнення крохмалю. З цитрусових знімайте забарвлену частину без зайвого білого гіркого шару; перед цим плоди мийте.`},{title:`Пов’язані теорії`,text:`038, 039, 053.`}]};var l=[38,39,53];var c=`References / Джерела`;var h=[`https://theicn.org/cicn/culinary-quick-bites-knife-skills/`,`https://hr.uky.edu/work-life-and-well-being/nutrition/food-preparation/knife-skills`,`https://extension.umn.edu/food/preparing/cooking-at-home/washing-fresh-fruits-and-vegetables`];var g={id:42,slug:s,group:`031`,title:a,en:n,ua:o,related:l,referenceTitle:c,references:h};export{g as default,n as en,i as group,r as id,c as referenceTitle,h as references,l as related,s as slug,a as title,o as ua};